@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{font-family:'DM Sans',sans-serif;color:#f5f2ee;background:#101114;font-synthesis:none;text-rendering:optimizeLegibility;--red:#ed483f;--blue:#59a9ff;--muted:#a19da0;--display:'Barlow Condensed',Impact,sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101114}button{font:inherit;color:inherit}#game{position:relative;width:100%;height:100%;min-height:540px;overflow:hidden;background:#101114;isolation:isolate}#scene{position:absolute;inset:0;z-index:-3}#scene canvas{display:block;width:100%;height:100%;touch-action:none}.vignette{position:absolute;inset:0;z-index:-2;pointer-events:none;background:linear-gradient(180deg,rgba(8,9,12,.64) 0%,rgba(9,10,14,.04) 28%,rgba(10,11,14,.08) 49%,rgba(11,12,15,.22) 68%,rgba(12,13,16,.91) 100%),linear-gradient(90deg,rgba(9,10,13,.4),transparent 27%,transparent 73%,rgba(9,10,13,.4));pointer-events:none}.grain{position:absolute;inset:0;z-index:5;pointer-events:none;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.88' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.16'/%3E%3C/svg%3E")}.topbar{position:absolute;z-index:8;top:0;left:0;right:0;height:74px;padding:0 4.5%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.09);background:linear-gradient(180deg,rgba(13,14,17,.5),transparent)}.brand{display:flex;align-items:center;gap:10px;color:#f8f6f1;text-decoration:none}.brand-mark{font:900 39px/.8 var(--display);letter-spacing:-4px;color:#f4f0e9}.brand-mark span{color:var(--red)}.brand-name{font:800 16px/.9 var(--display);letter-spacing:2px}.brand-name span{color:#aaa7a5}.event-pill{height:30px;display:flex;align-items:center;gap:10px;padding:0 13px;border:1px solid rgba(255,255,255,.17);background:rgba(13,14,17,.47);font-size:9px;font-weight:800;letter-spacing:1.55px;color:#d6d2d0}.event-pill i{width:3px;height:3px;background:#888;border-radius:50%}.live-dot{height:6px;width:6px;border-radius:50%;background:#ee4d45;box-shadow:0 0 10px #ed483f}.sound-btn{display:flex;align-items:center;gap:8px;background:transparent;border:0;color:#d5d0ca;font-size:9px;font-weight:800;letter-spacing:1.4px;cursor:pointer}.sound-icon{font-size:19px;color:#e04a41}.sound-btn.muted .sound-icon{color:#888}.fight-hud{position:absolute;z-index:6;top:95px;left:5%;right:5%;display:grid;grid-template-columns:1fr 132px 1fr;align-items:center;gap:3%;pointer-events:none}.fighter-card{min-width:0}.fighter-meta{display:flex;align-items:center;justify-content:space-between;margin-bottom:5px}.corner-tag{font-size:8px;font-weight:800;letter-spacing:1.7px}.red-tag{color:#ff6960}.blue-tag{color:#74b8ff}.fighter-record{font-size:9px;color:#b5b1b1;font-weight:600;letter-spacing:.8px}.fighter-name{font:800 clamp(20px,2.4vw,31px)/.95 var(--display);letter-spacing:.45px;white-space:nowrap}.fighter-name b{font-weight:500;color:#d1cdca}.opponent-card .fighter-name{text-align:right}.meter-row{margin-top:11px;display:flex;align-items:center;gap:8px}.meter-label{font-size:7px;letter-spacing:1.35px;font-weight:800;color:#b2adae;min-width:36px}.meter{height:5px;flex:1;background:rgba(255,255,255,.18);overflow:hidden}.meter i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#f65c4e,#cc2e2f);transition:width .25s ease;box-shadow:0 0 9px rgba(238,69,60,.55)}.opponent-card .meter i{background:linear-gradient(90deg,#3983d0,#69b6ff);box-shadow:0 0 9px rgba(74,158,240,.48)}.meter-row>b{font-size:8px;min-width:20px;text-align:right}.opponent-card .meter-row>b{text-align:left}.stamina-row{margin-top:7px}.stamina-meter i{background:linear-gradient(90deg,#c59b4c,#f4d276);box-shadow:0 0 8px rgba(227,185,90,.35)}.opponent-card .stamina-meter i{background:linear-gradient(90deg,#c59b4c,#f4d276)}.fight-clock{text-align:center;align-self:start;padding-top:1px}.round-label{display:block;font:700 10px var(--display);letter-spacing:2px;color:#eee9e4}.fight-clock strong{display:block;margin:0;font:800 37px/.95 var(--display);letter-spacing:1px;font-variant-numeric:tabular-nums}.clock-status{display:inline-flex;align-items:center;gap:5px;margin-top:5px;font-size:7px;letter-spacing:1.7px;color:#d1cdca;font-weight:800}.clock-status i{width:5px;height:5px;border-radius:50%;background:#d6c26c}.clock-status.live i{background:#e94b43;box-shadow:0 0 7px #e94b43;animation:pulse 1s infinite}.round-banner{position:absolute;z-index:7;left:50%;top:47%;transform:translate(-50%,-50%) scale(.8);opacity:0;text-align:center;pointer-events:none;text-shadow:0 5px 35px #000;transition:opacity .3s,transform .3s}.round-banner.show{opacity:1;transform:translate(-50%,-50%) scale(1)}.round-banner span{display:block;font:700 16px var(--display);letter-spacing:6px}.round-banner b{font:900 clamp(75px,13vw,160px)/.83 var(--display);letter-spacing:7px}.intro-card,.result-card{position:absolute;z-index:9;left:50%;top:49%;transform:translate(-50%,-50%);width:min(430px,calc(100% - 34px));padding:27px 31px 22px;background:linear-gradient(135deg,rgba(17,18,21,.94),rgba(22,22,25,.89));border:1px solid rgba(255,255,255,.15);box-shadow:0 24px 80px rgba(0,0,0,.4);backdrop-filter:blur(16px);transition:opacity .3s,transform .3s}.intro-card::before,.result-card::before{content:'';position:absolute;top:-1px;left:29px;width:56px;height:2px;background:var(--red);box-shadow:0 0 15px rgba(237,72,63,.7)}.intro-card.hidden,.result-card.hidden{opacity:0;pointer-events:none;transform:translate(-50%,-46%) scale(.97)}.intro-kicker,.result-kicker{display:flex;align-items:center;gap:9px;color:#b6b1b0;font-size:8px;font-weight:800;letter-spacing:1.8px}.intro-kicker span{color:#fa6258}.intro-kicker i{height:1px;width:24px;background:#6c6766}.intro-card h1,.result-card h2{margin:16px 0 5px;font:900 clamp(53px,8vw,77px)/.78 var(--display);letter-spacing:1px}.intro-card h1 em{font-style:normal;color:var(--red)}.intro-card p,.result-card p{margin:14px 0 17px;color:#bdb9b6;font-size:11px;line-height:1.6}.intro-versus{height:39px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid rgba(255,255,255,.11);border-bottom:1px solid rgba(255,255,255,.11);font-size:9px;letter-spacing:.7px}.intro-versus div{display:flex;align-items:center;gap:7px}.vs-dot{width:7px;height:7px;border-radius:50%}.red-dot{background:var(--red);box-shadow:0 0 8px #ed483f}.blue-dot{background:var(--blue);box-shadow:0 0 8px #59a9ff}.versus{font:800 15px var(--display);color:#908b8b}.start-btn{position:relative;width:100%;height:47px;margin-top:16px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;background:var(--red);border:0;cursor:pointer;font-size:10px;font-weight:800;letter-spacing:1.7px;transition:background .2s,transform .2s}.start-btn:hover{background:#ff5b50;transform:translateY(-1px)}.start-btn b{font-size:19px;font-weight:500}.intro-foot{display:flex;justify-content:space-between;margin-top:14px;color:#888384;font-size:7px;font-weight:700;letter-spacing:1.2px}.result-card{text-align:center}.result-card .result-kicker{justify-content:center}.result-card h2{color:#f4f0e9}.result-card p{margin:10px 0}.fight-tip{position:absolute;z-index:4;bottom:146px;left:50%;transform:translateX(-50%);padding:8px 13px;display:flex;align-items:center;gap:8px;border:1px solid rgba(255,255,255,.14);background:rgba(15,16,19,.57);font-size:9px;color:#c9c4c0;white-space:nowrap;transition:opacity .4s}.fight-tip b{color:#fff}.tip-icon{color:#e8c568}.combo-callout{position:absolute;z-index:7;top:39%;left:50%;transform:translate(-50%,-50%) scale(.7);opacity:0;font:900 28px var(--display);letter-spacing:3px;color:#f1d27b;text-shadow:0 0 18px rgba(241,210,123,.7);pointer-events:none;transition:opacity .15s,transform .15s}.combo-callout.show{opacity:1;transform:translate(-50%,-50%) scale(1)}.hit-flash{position:absolute;z-index:3;inset:0;background:rgba(238,61,52,.24);opacity:0;pointer-events:none}.hit-flash.flash{animation:flash .2s ease-out}.mobile-controls{position:absolute;z-index:8;bottom:34px;left:5%;right:5%;height:128px;display:flex;align-items:end;justify-content:space-between;pointer-events:none}.movement-control,.action-controls{pointer-events:auto}.control-caption{margin:0 0 7px 5px;color:#c9c3c0;font-size:8px;font-weight:800;letter-spacing:2px}.joystick{width:104px;height:104px;touch-action:none;user-select:none;display:grid;place-items:center}.joy-ring{position:relative;width:91px;height:91px;border-radius:50%;border:1px solid rgba(255,255,255,.2);background:radial-gradient(circle,rgba(255,255,255,.04),rgba(0,0,0,.22));box-shadow:inset 0 0 22px rgba(0,0,0,.28),0 8px 25px rgba(0,0,0,.2)}.joy-ring>i{position:absolute;left:50%;top:50%;width:1px;height:80%;background:rgba(255,255,255,.12);transform-origin:center}.joy-ring>i:nth-child(1){transform:translate(-50%,-50%)}.joy-ring>i:nth-child(2){transform:translate(-50%,-50%) rotate(60deg)}.joy-ring>i:nth-child(3){transform:translate(-50%,-50%) rotate(120deg)}.joy-knob{position:absolute;left:50%;top:50%;width:39px;height:39px;border-radius:50%;transform:translate(-50%,-50%);background:linear-gradient(145deg,rgba(244,242,235,.78),rgba(112,111,113,.57));border:1px solid rgba(255,255,255,.48);box-shadow:0 4px 12px rgba(0,0,0,.35);transition:background .1s}.move-hint{margin:4px 0 0 2px;display:flex;gap:6px;align-items:center;color:#aaa5a4;font-size:7px;font-weight:800;letter-spacing:1px}.move-hint span{font-size:12px;color:#f5f2ee}.action-controls{display:flex;align-items:end;gap:9px}.action-btn{width:61px;height:61px;border-radius:50%;padding:0;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px;border:1px solid rgba(255,255,255,.23);background:linear-gradient(145deg,rgba(44,45,49,.9),rgba(19,20,23,.9));box-shadow:0 5px 18px rgba(0,0,0,.28);cursor:pointer;touch-action:none;user-select:none;transition:transform .1s,filter .1s,border-color .1s}.action-btn:active,.action-btn.pressed{transform:scale(.92);filter:brightness(1.35)}.action-symbol{font-size:19px;line-height:20px;color:#eee}.action-btn>span:last-child{font-size:7px;font-weight:800;letter-spacing:.7px;color:#d3d0cf}.jab-btn{width:73px;height:73px;border-color:rgba(237,72,63,.78);background:linear-gradient(145deg,#ee574b,#ae282d);box-shadow:0 0 25px rgba(237,72,63,.25),0 5px 18px rgba(0,0,0,.3)}.jab-btn .action-symbol{font-size:25px}.kick-btn{margin:0 5px 9px 0;width:67px;height:67px;border-color:rgba(86,160,231,.59)}.heavy-btn{margin-bottom:27px;border-color:rgba(235,192,99,.59)}.dodge-btn{margin-bottom:5px;width:53px;height:53px}.guard-btn{margin-bottom:0;width:58px;height:58px}.keyboard-hint{position:absolute;z-index:4;bottom:15px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#a6a1a0;font-size:7px;font-weight:700;letter-spacing:1.4px}.keyboard-hint kbd{padding:3px 5px;margin:0 4px 0 9px;border:1px solid rgba(255,255,255,.24);background:rgba(15,16,19,.45);color:#e9e5e2;font:700 8px 'DM Sans',sans-serif}.bottom-brand{position:absolute;z-index:4;right:4.7%;bottom:18px;display:flex;align-items:center;gap:7px;color:rgba(239,234,228,.55);font:700 8px var(--display);letter-spacing:1.3px}.bottom-brand span{font:900 11px var(--display);color:var(--red)}.bottom-brand i{height:1px;width:16px;background:rgba(255,255,255,.28)}@keyframes pulse{50%{opacity:.35}}@keyframes flash{0%{opacity:1}100%{opacity:0}}
@media(max-width:700px){#game{min-height:500px}.topbar{height:58px;padding:0 5%}.brand-mark{font-size:32px}.brand-name{font-size:14px}.event-pill{gap:7px;padding:0 9px;font-size:7px;letter-spacing:1px}.sound-label{display:none}.fight-hud{top:73px;left:4%;right:4%;grid-template-columns:1fr 70px 1fr;gap:2%}.fighter-name{font-size:clamp(16px,4.35vw,25px);letter-spacing:0}.fighter-record{font-size:8px}.corner-tag{font-size:6px;letter-spacing:1px}.meter-label{font-size:6px;min-width:28px}.meter-row{gap:5px;margin-top:9px}.meter{height:4px}.fight-clock strong{font-size:30px}.round-label{font-size:8px}.clock-status{font-size:6px;letter-spacing:1px}.intro-card,.result-card{top:46%;padding:22px 23px 18px;width:min(390px,calc(100% - 34px))}.intro-card h1,.result-card h2{font-size:62px}.intro-card p{font-size:10px}.fight-tip{bottom:141px;font-size:8px}.mobile-controls{left:4%;right:4%;bottom:26px;height:115px}.joystick{width:86px;height:91px}.joy-ring{width:77px;height:77px}.joy-knob{width:34px;height:34px}.action-controls{gap:5px}.action-btn{width:49px;height:49px}.action-btn>span:last-child{font-size:6px}.action-symbol{font-size:16px;line-height:17px}.jab-btn{width:61px;height:61px}.jab-btn .action-symbol{font-size:22px}.kick-btn{width:54px;height:54px;margin-right:2px}.heavy-btn{margin-bottom:21px}.dodge-btn{width:44px;height:44px}.guard-btn{width:47px;height:47px}.move-hint{font-size:6px;gap:4px}.keyboard-hint{display:none}.bottom-brand{display:none}.round-banner{top:44%}.fight-tip{max-width:85vw}}
@media(max-width:380px){.event-pill{gap:5px;font-size:6px}.fight-hud{grid-template-columns:1fr 60px 1fr}.fighter-name{font-size:15px}.action-controls{gap:3px}.action-btn{width:44px;height:44px}.jab-btn{width:56px;height:56px}.kick-btn{width:49px;height:49px}.heavy-btn{margin-bottom:18px}.dodge-btn{width:41px;height:41px}.guard-btn{width:43px;height:43px}.joystick{width:75px}.joy-ring{width:69px;height:69px}}
@media(max-height:650px){.fight-hud{top:73px}.intro-card{top:47%;padding:17px 23px 14px}.intro-card h1{font-size:56px;margin-top:12px}.intro-card p{margin:9px 0 12px}.start-btn{height:42px;margin-top:12px}.fight-tip{bottom:126px}.mobile-controls{bottom:18px;height:103px}.joystick{height:84px}.keyboard-hint,.bottom-brand{display:none}}

import * as THREE from 'three';

const $ = (id) => document.getElementById(id);
const sceneHost = $('scene');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x12141a);
scene.fog = new THREE.FogExp2(0x12141a, 0.035);
const camera = new THREE.PerspectiveCamera(36, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 5.2, 14.7);
camera.lookAt(0, 2.45, 0);
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
sceneHost.appendChild(renderer.domElement);

scene.add(new THREE.HemisphereLight(0xc9d9ff, 0x201517, 2.15));
const keyLight = new THREE.DirectionalLight(0xffdfc5, 3.2);
keyLight.position.set(-5, 9, 7); keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024); keyLight.shadow.camera.left = -8; keyLight.shadow.camera.right = 8; keyLight.shadow.camera.top = 9; keyLight.shadow.camera.bottom = -6;
scene.add(keyLight);
const coolLight = new THREE.DirectionalLight(0x5b8fff, 2.1); coolLight.position.set(5, 6, -5); scene.add(coolLight);
const redLight = new THREE.SpotLight(0xff594a, 170, 22, Math.PI / 5, 0.45, 1.5); redLight.position.set(-5, 8, 3); redLight.target.position.set(-1, 0, 0); scene.add(redLight, redLight.target);
const blueLight = new THREE.SpotLight(0x438cff, 180, 22, Math.PI / 5, 0.45, 1.5); blueLight.position.set(5, 8, -3); blueLight.target.position.set(1, 0, 0); scene.add(blueLight, blueLight.target);

const mat = (color, roughness = 0.8, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const floorMat = new THREE.MeshStandardMaterial({ color: 0x25272a, roughness: .91 });
const cageMat = new THREE.MeshStandardMaterial({ color: 0x11151a, roughness: .72, metalness: .32 });
const addBox = (parent, size, material, pos, cast = false) => { const m = new THREE.Mesh(new THREE.BoxGeometry(...size), material); m.position.set(...pos); m.castShadow = cast; m.receiveShadow = true; parent.add(m); return m; };
const octagon = (radius, y, material, tube = .035) => {
  const points = Array.from({ length: 9 }, (_, i) => { const a = Math.PI / 8 + i * Math.PI / 4; return new THREE.Vector3(Math.cos(a) * radius, y, Math.sin(a) * radius); });
  const curve = new THREE.CatmullRomCurve3(points, false, 'centripetal'); const mesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 160, tube, 7, false), material); scene.add(mesh); return mesh;
};

function makeArena() {
  const platform = new THREE.Mesh(new THREE.CylinderGeometry(6.7, 6.7, .35, 8), mat(0x151619, .85, .15));
  platform.rotation.y = Math.PI / 8; platform.position.y = -.24; platform.receiveShadow = true; platform.castShadow = true; scene.add(platform);
  const matSurface = new THREE.Mesh(new THREE.CircleGeometry(6.31, 8), floorMat); matSurface.rotation.x = -Math.PI / 2; matSurface.rotation.z = Math.PI / 8; matSurface.position.y = -.045; matSurface.receiveShadow = true; scene.add(matSurface);
  const centerLine = new THREE.Mesh(new THREE.RingGeometry(1.37, 1.4, 8), mat(0x74767a, .86)); centerLine.rotation.x = -Math.PI / 2; centerLine.rotation.z = Math.PI / 8; centerLine.position.y = -.032; scene.add(centerLine);
  const redCorner = new THREE.Mesh(new THREE.CircleGeometry(.83, 8), mat(0x692426)); redCorner.rotation.x = -Math.PI / 2; redCorner.rotation.z = Math.PI / 8; redCorner.position.set(-3.85, -.027, .3); scene.add(redCorner);
  const blueCorner = new THREE.Mesh(new THREE.CircleGeometry(.83, 8), mat(0x1e4166)); blueCorner.rotation.x = -Math.PI / 2; blueCorner.rotation.z = Math.PI / 8; blueCorner.position.set(3.85, -.027, -.3); scene.add(blueCorner);
  octagon(6.31, .03, mat(0x98989b, .6, .2), .045);
  // Cage fence segments follow the eight sides; fine crossed wires are deliberately lightweight.
  const r = 6.34, sides = 8;
  for (let i = 0; i < sides; i++) {
    const a1 = Math.PI / 8 + i * Math.PI / 4, a2 = Math.PI / 8 + (i + 1) * Math.PI / 4;
    const p1 = new THREE.Vector3(Math.cos(a1) * r, 0, Math.sin(a1) * r), p2 = new THREE.Vector3(Math.cos(a2) * r, 0, Math.sin(a2) * r);
    const mid = p1.clone().add(p2).multiplyScalar(.5); const len = p1.distanceTo(p2); const angle = Math.atan2(p2.z - p1.z, p2.x - p1.x);
    const panel = new THREE.Mesh(new THREE.PlaneGeometry(len, 3.35), new THREE.MeshBasicMaterial({ color: 0x82909a, transparent: true, opacity: .14, side: THREE.DoubleSide, depthWrite: false }));
    panel.position.set(mid.x, 1.72, mid.z); panel.rotation.y = -angle; scene.add(panel);
    for (let j = 0; j <= 10; j++) {
      const x = -len / 2 + len * j / 10;
      const pts = [new THREE.Vector3(x, .12, 0), new THREE.Vector3(x + (j % 2 ? -len / 10 : len / 10), 3.35, 0)];
      const wire = new THREE.BufferGeometry().setFromPoints(pts); const w = new THREE.Line(wire, new THREE.LineBasicMaterial({ color: 0x89949b, transparent: true, opacity: .14 }));
      w.position.set(mid.x, 0, mid.z); w.rotation.y = -angle; scene.add(w);
    }
    const rail = addBox(scene, [len, .1, .1], cageMat, [mid.x, 3.4, mid.z]); rail.rotation.y = -angle;
    const lowerRail = addBox(scene, [len, .055, .055], mat(0x33373c, .5, .25), [mid.x, .13, mid.z]); lowerRail.rotation.y = -angle;
    const post = new THREE.Mesh(new THREE.CylinderGeometry(.075, .085, 3.6, 8), mat(0x25292e, .46, .4)); post.position.set(p1.x, 1.72, p1.z); post.castShadow = true; scene.add(post);
  }
  octagon(6.4, 3.42, cageMat, .07);
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(200, 200), mat(0x111216, 1)); ground.rotation.x = -Math.PI / 2; ground.position.y = -.48; ground.receiveShadow = true; scene.add(ground);
  // Blurred crowd: thousands of low-poly silhouettes and soft arena lights.
  const crowdGeo = new THREE.BufferGeometry(), positions = [], colors = [];
  const palette = [0x4c3a36, 0x353c49, 0x6a5550, 0x293d4d, 0x4d4a47, 0x7d3434, 0x56606a];
  for (let i = 0; i < 1600; i++) {
    const angle = Math.random() * Math.PI * 2; const radius = 8.5 + Math.random() * 5.5;
    positions.push(Math.cos(angle) * radius, .7 + Math.random() * 3.5, Math.sin(angle) * radius - 1);
    const c = new THREE.Color(palette[Math.floor(Math.random() * palette.length)]); colors.push(c.r, c.g, c.b);
  }
  crowdGeo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3)); crowdGeo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  const crowd = new THREE.Points(crowdGeo, new THREE.PointsMaterial({ size: .095, vertexColors: true, sizeAttenuation: true, transparent: true, opacity: .73 })); scene.add(crowd);
  for (let i = 0; i < 14; i++) { const l = new THREE.PointLight(i % 3 ? 0x555f7b : 0x9b4838, 5, 7); const a = i / 14 * Math.PI * 2; l.position.set(Math.cos(a) * 9.5, 4.5 + Math.sin(i * 3) * .5, Math.sin(a) * 9.5); scene.add(l); }
}
